-- Colunas da tabela exercises
SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'exercises' AND TABLE_SCHEMA = DATABASE();

-- Total de professores e sem voz
SELECT COUNT(*) as total_teachers, SUM(CASE WHEN voice_id IS NULL OR voice_id = '' THEN 1 ELSE 0 END) as no_voice FROM virtual_teachers;

-- Total de exercícios
SELECT COUNT(*) as total_exercises FROM exercises;

-- Total de lições
SELECT COUNT(*) as total_lessons FROM lessons;

